fun apply(e: Event) {
    val delta = when (e.kind) {
        "AUTHORIZED" -> return                                // reserves money, moves none
        "CAPTURED" -> e.cents                                 // money moves on the capture's day
        "REFUNDED" -> -e.cents                                // and back on the refund's day
        else -> error("unknown kind ${e.kind}")
    }
    totals.merge(e.merchant to e.day, delta, Long::plus)
}

fun rebuild(log: List<Event>) {
    totals.clear()                                            // start empty: safe to run twice
    for (e in log) apply(e)                                   // offset 0 to the end, in order
}

